/**
 * ═══════════════════════════════════════════════════════════════════════════
 *  μNode32U4 — bare ATmega32U4 USB dev board (SINGLE-FILE PLAYGROUND COPY)
 * ═══════════════════════════════════════════════════════════════════════════
 *  Paste this whole file into https://snippets.tscircuit.com (or any tscircuit
 *  playground) to view the PCB, schematic and 3D model interactively.
 *
 *  GENERATED by extras/build_standalone.py from lib/*.tsx + index.tsx —
 *  do not edit by hand; edit the sources and re-run the script.
 */
interface CommonLayoutProps {
  [key: string]: any
}


/**
 * ─────────────────────────────────────────────────────────────────────────
 *  lib/atmega32u4.tsx — A reusable "bare chip" component for the
 *  Microchip ATmega32U4 (TQFP-44 package).
 * ─────────────────────────────────────────────────────────────────────────
 *
 *  WHY THIS FILE EXISTS
 *  In tscircuit, a chip is just a React component. You describe it ONCE —
 *  package footprint, pin names, schematic pin arrangement — and then you
 *  can drop `<Atmega32U4 name="U1" />` onto any board, the same way you'd
 *  place a part in a schematic library in KiCad/Altium.
 *
 *  THE PIN TABLE BELOW IS NOT FROM MEMORY — it is the *physical* TQFP-44
 *  pinout from the Microchip datasheet (Atmel-7766J, Fig. 1-1), verified
 *  against the official Arduino Leonardo schematic and the ArduinoCore-avr
 *  "leonardo" variant files. tscircuit's `tqfp44_p0.8mm` footprint numbers
 *  pins counter-clockwise starting at the top-left, exactly like the datasheet:
 *
 *      pin 1  = top of LEFT edge   (PE6)
 *      pins 1..11   go DOWN the left edge      (USB pins 2-7 live here!)
 *      pins 12..22  go RIGHT across the bottom (RESET, XTAL, PORTD)
 *      pins 23..33  go UP the right edge       (PORTB/PC6/PC7/PE2)
 *      pins 34..44  go LEFT across the top     (analog PORTF, AVCC)
 *
 *  Pin-label uniqueness matters: tscircuit turns every label into a
 *  *selectable port* (e.g. `.U1 > .VCC1`). Labels must therefore be unique
 *  per chip — that's why the two VCC pins are VCC1/VCC2, the two AVCC pins
 *  AVCC1/AVCC2 and the four GND pins GND1..GND4.
 *
 *  ⚠️ PIN 24 IS AVCC, NOT VCC. The 32U4 has TWO analog-supply pins: 24
 *  (ADC8-ADC13 side) and 44 (ADC0-ADC7 side) — datasheet Fig. 1-1, and the
 *  note under Fig. 24-10: "the same circuitry should be used for AVCC
 *  filtering on the ADC8-ADC13 side". Only pins 14 and 34 are VCC.
 *  (An earlier revision of this file labelled pin 24 "VCC2" — wrong.)
 */

export interface Atmega32U4Props extends CommonLayoutProps {
  /** Reference designator, e.g. "U1" */
  name: string
}

/**
 * The full 44-pin map. Keys are physical pin numbers (`pin1`..`pin44`),
 * values become the port names you use in traces and the labels you see
 * in the schematic view.
 */
export const ATMEGA32U4_PINOUT = {
  // ── LEFT EDGE (top → bottom) ─────────────────────────────────────────
  pin1: "PE6", // INT6/AIN0  — Arduino D7
  pin2: "UVCC", // USB pad supply input (tie to 5V)
  pin3: "DMINUS", // USB D− (via 22Ω series resistor — datasheet §2.2.8)
  pin4: "DPLUS", // USB D+ (via 22Ω series resistor — datasheet §2.2.9)
  pin5: "UGND", // USB pad ground
  pin6: "UCAP", // Internal 3.3V regulator output → 1µF cap to GND (§2.2.12)
  pin7: "VBUS", // VBUS monitor input
  pin8: "PB0", // SS/PCINT0 — Arduino D17, wired to the RX LED
  pin9: "PB1", // SCK — ICSP SCK, Arduino D15
  pin10: "PB2", // MOSI — ICSP MOSI, Arduino D16
  pin11: "PB3", // MISO — ICSP MISO, Arduino D14
  // ── BOTTOM EDGE (left → right) ───────────────────────────────────────
  pin12: "PB7", // OC0A/OC1C — Arduino D11 (PWM)
  pin13: "RESET", // active-low reset (10k pull-up + button)
  pin14: "VCC1", // digital +5V #1 (needs its own 100nF decoupler)
  pin15: "GND1",
  pin16: "XTAL2", // 16MHz crystal
  pin17: "XTAL1", // 16MHz crystal
  pin18: "PD0", // INT0/SCL — Arduino D3 / I²C clock
  pin19: "PD1", // INT1/SDA — Arduino D2 / I²C data
  pin20: "PD2", // RXD1 — Arduino D0
  pin21: "PD3", // TXD1 — Arduino D1
  pin22: "PD5", // XCK1/CTS — TX LED pin (firmware-driven)
  // ── RIGHT EDGE (bottom → top) ────────────────────────────────────────
  pin23: "GND2",
  pin24: "AVCC1", // analog supply #1 (ADC8-13 side) — filtered, 100nF at pin
  pin25: "PD4", // ICP1/ADC8 — Arduino D4 / A6
  pin26: "PD6", // T1/ADC9 — Arduino D12 / A11
  pin27: "PD7", // OC4D/ADC10 — Arduino D6 / A7 (PWM)
  pin28: "PB4", // ADC11 — Arduino D8 / A8
  pin29: "PB5", // OC1A/ADC12 — Arduino D9 / A9 (PWM)
  pin30: "PB6", // OC1B/ADC13 — Arduino D10 / A10 (PWM)
  pin31: "PC6", // OC3A/OC4A — Arduino D5 (PWM)
  pin32: "PC7", // ICP3/CLK0/OC4A — Arduino D13, the "L" LED
  pin33: "PE2", // #HWB — hardware bootloader pin (active-low, needs pull-up)
  // ── TOP EDGE (right → left) ──────────────────────────────────────────
  pin34: "VCC2", // digital +5V #2 (needs its own 100nF decoupler)
  pin35: "GND3",
  pin36: "PF7", // ADC7/TDI — Arduino A0
  pin37: "PF6", // ADC6/TDO — Arduino A1
  pin38: "PF5", // ADC5/TMS — Arduino A2
  pin39: "PF4", // ADC4/TCK — Arduino A3
  pin40: "PF1", // ADC1 — Arduino A4
  pin41: "PF0", // ADC0 — Arduino A5
  pin42: "AREF", // ADC reference (100nF to GND if you use it)
  pin43: "GND4",
  pin44: "AVCC2", // analog supply #2 (ADC0-7 side) — filtered, 100nF at pin
} as const

export const Atmega32U4 = (props: Atmega32U4Props) => (
  <chip
    // `footprint="tqfp44_p0.8mm_w10mm"` is a *footprinter string* — tscircuit
    // generates a 44-pad TQFP land pattern (and a 3D model!) from it.
    //
    // ⚠️ THE _p0.8mm SUFFIX IS NOT OPTIONAL. tscircuit's tqfp footprinter
    // defaults to a 0.5mm pin pitch for 44+ pin packages, but the
    // ATmega32U4-AU's TQFP-44 is a 10×10mm body with a **0.8mm** pitch
    // (datasheet §1 / package drawing 44TQFP-101). Without the override,
    // the PCB would be un-buildable with the real chip — a textbook example
    // of why you always check generated footprints against the package
    // drawing before ordering boards. The 0.8mm pitch also leaves 0.5mm
    // routing channels between the 0.3mm pads, which the fan-out needs.
    footprint="tqfp44_p0.8mm_w10mm"
    pinLabels={ATMEGA32U4_PINOUT}
    manufacturerPartNumber="ATmega32U4-AU"
    // Schematic-box layout: all power/USB/clock/control pins on the left,
    // every GPIO on the right. This is what makes the schematic readable.
    schPinArrangement={{
      leftSide: {
        direction: "top-to-bottom",
        pins: [
          "VBUS", "UVCC", "UCAP", "UGND", "DMINUS", "DPLUS",
          "XTAL1", "XTAL2", "RESET", "PE2", "AREF", "AVCC1", "AVCC2",
          "VCC1", "VCC2", "GND1", "GND2", "GND3", "GND4",
        ],
      },
      rightSide: {
        direction: "top-to-bottom",
        pins: [
          "PE6",
          "PB0", "PB1", "PB2", "PB3", "PB4", "PB5", "PB6", "PB7",
          "PC6", "PC7",
          "PD0", "PD1", "PD2", "PD3", "PD4", "PD5", "PD6", "PD7",
          "PF0", "PF1", "PF4", "PF5", "PF6", "PF7",
        ],
      },
    }}
    {...props}
  />
)

/**
 * ─────────────────────────────────────────────────────────────────────────
 *  lib/usb-micro-b.tsx — Micro-USB-B receptacle: Amphenol ICC 10118194-0001LF
 * ─────────────────────────────────────────────────────────────────────────
 *
 *  WHY A HAND-BUILT FOOTPRINT?
 *  tscircuit's footprinter knows standard patterns (tqfp44, 0603, hc49...),
 *  but connectors are mechanical parts with vendor-specific land patterns.
 *  For those you compose a footprint from primitive elements:
 *
 *    <smtpad />       → a surface-mount copper pad (can carry a port name)
 *    <platedhole />   → a plated through-hole (here: oval "pill" shell legs)
 *    <silkscreenpath /> → silkscreen outline graphics
 *
 *  SOURCE OF EVERY NUMBER BELOW
 *  The pads are transcribed from the KiCad library footprint
 *  Connector_USB:USB_Micro-B_Amphenol_10118194_Horizontal, which the KiCad
 *  library team builds from Amphenol's 10118194 customer drawing. Only a
 *  rotation was applied: KiCad's origin is kept, and its "+Y = toward the
 *  board edge" axis becomes −X here, so the cable opening faces LEFT.
 *  A footprint is part-specific: order exactly 10118194-0001LF (or another
 *  10118194-xxxxLF variant with the same drawing).
 *
 *  GEOMETRY (top view, opening facing −X):
 *    - 5 signal pads 1.35 × 0.40 mm, 0.65 mm pitch, centred at x = +1.40
 *      top → bottom: 1 VBUS, 2 D−, 3 D+, 4 ID, 5 GND
 *    - 4 oval through-hole shell legs (the mechanical anchor that makes a
 *      micro-B connector survive real cable abuse) + 4 SMD shell pads
 *    - PCB EDGE at x = −2.75: the connector body overhangs it by 0.70 mm,
 *      so a plug's overmold clears the board. Place the component so that
 *      pcbX − 2.75 equals the board's left edge.
 */

export interface UsbMicroBProps extends CommonLayoutProps {
  name: string
}

/** distance from the footprint origin to the board edge it must sit on */
export const USB_MICRO_B_EDGE_OFFSET_MM = 2.75

export const UsbMicroB = (props: UsbMicroBProps) => (
  <chip
    {...props}
    manufacturerPartNumber="10118194-0001LF"
    // pinLabels bind each pad's `portHints` name to a pin number, so
    // selectors like ".J1 > .VBUS" resolve to pad 1. The six SHIELD ports
    // are the shell: every one of them is tied to GND in index.tsx.
    pinLabels={{
      pin1: "VBUS",
      pin2: "DMINUS",
      pin3: "DPLUS",
      pin4: "ID",
      pin5: "GND",
      pin6: "SHIELD1",
      pin7: "SHIELD2",
      pin8: "SHIELD3",
      pin9: "SHIELD4",
      pin10: "SHIELD5",
      pin11: "SHIELD6",
    }}
    footprint={
      <footprint>
        {/* ── signal pads (KiCad pads 1-5: 0.40 × 1.35 at y = −1.40) ── */}
        <smtpad portHints={["VBUS"]} pcbX="1.4mm" pcbY="1.3mm" width="1.35mm" height="0.4mm" shape="rect" />
        <smtpad portHints={["DMINUS"]} pcbX="1.4mm" pcbY="0.65mm" width="1.35mm" height="0.4mm" shape="rect" />
        <smtpad portHints={["DPLUS"]} pcbX="1.4mm" pcbY="0mm" width="1.35mm" height="0.4mm" shape="rect" />
        {/* ID (pin 4) is only used by OTG cables — left unconnected here */}
        <smtpad portHints={["ID"]} pcbX="1.4mm" pcbY="-0.65mm" width="1.35mm" height="0.4mm" shape="rect" />
        <smtpad portHints={["GND"]} pcbX="1.4mm" pcbY="-1.3mm" width="1.35mm" height="0.4mm" shape="rect" />

        {/* ── rear shell legs: oval holes 0.55 × 0.85, pads 0.95 × 1.25 ── */}
        <platedhole portHints={["SHIELD1"]} shape="pill" pcbX="1.4mm" pcbY="2.5mm" outerWidth="0.95mm" outerHeight="1.25mm" holeWidth="0.55mm" holeHeight="0.85mm" />
        <platedhole portHints={["SHIELD2"]} shape="pill" pcbX="1.4mm" pcbY="-2.5mm" outerWidth="0.95mm" outerHeight="1.25mm" holeWidth="0.55mm" holeHeight="0.85mm" />

        {/* ── front shell legs: oval holes 1.15 × 0.50 with their SMD tabs ── */}
        <platedhole portHints={["SHIELD3"]} shape="pill" pcbX="-1.3mm" pcbY="3.5mm" outerWidth="1.55mm" outerHeight="0.89mm" holeWidth="1.15mm" holeHeight="0.5mm" />
        <smtpad portHints={["SHIELD3"]} pcbX="-1.3mm" pcbY="3.025mm" width="1.55mm" height="1.45mm" shape="rect" />
        <platedhole portHints={["SHIELD4"]} shape="pill" pcbX="-1.3mm" pcbY="-3.5mm" outerWidth="1.55mm" outerHeight="0.89mm" holeWidth="1.15mm" holeHeight="0.5mm" />
        <smtpad portHints={["SHIELD4"]} pcbX="-1.3mm" pcbY="-3.025mm" width="1.55mm" height="1.45mm" shape="rect" />

        {/* ── inner SMD shell pads ── */}
        <smtpad portHints={["SHIELD5"]} pcbX="-1.3mm" pcbY="1mm" width="1.55mm" height="1.5mm" shape="rect" />
        <smtpad portHints={["SHIELD6"]} pcbX="-1.3mm" pcbY="-1mm" width="1.55mm" height="1.5mm" shape="rect" />

        {/* ── silkscreen: body sides (kept clear of every pad) ── */}
        <silkscreenpath route={[{ x: -2.75, y: 4.3 }, { x: 0.6, y: 4.3 }]} />
        <silkscreenpath route={[{ x: -2.75, y: -4.3 }, { x: 0.6, y: -4.3 }]} />
        {/* pin-1 (VBUS) tick behind the signal pads */}
        <silkscreenpath route={[{ x: 2.4, y: 1.3 }, { x: 2.9, y: 1.3 }]} />
      </footprint>
    }
    // Schematic-box pin arrangement, wired like a classic USB connector:
    // VBUS on top, then the pair, then GND/shield.
    schPinArrangement={{
      leftSide: {
        direction: "top-to-bottom",
        pins: ["VBUS", "DPLUS", "DMINUS", "GND", "SHIELD1", "SHIELD2", "SHIELD3", "SHIELD4", "SHIELD5", "SHIELD6"],
      },
      rightSide: {
        direction: "top-to-bottom",
        pins: ["ID"],
      },
    }}
  />
)

/**
 * ─────────────────────────────────────────────────────────────────────────
 *  lib/ferrite-bead.tsx — 0603 chip ferrite bead
 * ─────────────────────────────────────────────────────────────────────────
 *
 *  tscircuit has no dedicated ferrite-bead element, and modelling a bead as
 *  an <inductor> puts a misleading "µH" value on the schematic and BOM. A
 *  bead is specified by its IMPEDANCE at 100 MHz (and its DC resistance and
 *  current rating), so it is described here as a two-pin part carrying its
 *  real manufacturer part number.
 *
 *  Default part: Murata BLM18PG221SN1D — 220 Ω @ 100 MHz, 0603, low DCR.
 *  Any 0603 bead of 120-600 Ω @ 100 MHz with DCR ≤ 0.3 Ω and ≥ 200 mA rating
 *  works for the ATmega32U4's AVCC pins (they draw well under 10 mA).
 */

export interface FerriteBeadProps extends CommonLayoutProps {
  name: string
  manufacturerPartNumber?: string
}

export const FerriteBead = ({ manufacturerPartNumber = "BLM18PG221SN1D", ...props }: FerriteBeadProps) => (
  <chip
    {...props}
    footprint="0603"
    manufacturerPartNumber={manufacturerPartNumber}
    pinLabels={{ pin1: "IN", pin2: "OUT" }}
    schPinArrangement={{
      leftSide: { direction: "top-to-bottom", pins: ["IN"] },
      rightSide: { direction: "top-to-bottom", pins: ["OUT"] },
    }}
  />
)

/**
 * ═════════════════════════════════════════════════════════════════════════
 *  μNode32U4 — a bare-chip USB dev board, in tscircuit
 * ═════════════════════════════════════════════════════════════════════════
 *  Run with:   npm install -g tscircuit   →   tsci dev
 *  (or paste the standalone copy in standalone/ into snippets.tscircuit.com)
 *
 *  WHAT THIS IS
 *  An Arduino-Leonardo-class board built from FIRST PRINCIPLES: one bare
 *  ATmega32U4 (TQFP-44) plus ~35 primary components — no dev-board module
 *  anywhere. USB device, 16MHz crystal clock, reset & bootloader circuits,
 *  ICSP header, four indicators, I²C pull-ups, and every GPIO on 2.54mm
 *  headers with Leonardo-compatible pin names (D0-D13, A0-A5, SDA/SCL,
 *  MISO/SCK/MOSI/SS). Flash the Caterina bootloader over ICSP, select
 *  "Arduino Leonardo" in the IDE, and it just works.
 *
 *  HOW TO READ THIS FILE
 *  It's one flat "netlist" organized into banner-commented sections that
 *  mirror the schematic pages of a real design: USB front-end → power
 *  integrity → clock → reset/boot → ICSP → indicators → I²C → breakouts.
 *  Every wire on the board exists as an explicit <trace /> — reading the
 *  traces top-to-bottom IS reading the schematic.
 *
 *  NET CONVENTIONS
 *  Point-to-point wires are direct traces (with a `name` so the schematic
 *  shows a net label). Anything touching 3+ places gets a named net
 *  (net.V5, net.GND, net.RST...) — exactly like net labels in KiCad.
 */

const BOARD_W = 72

export default () => (
  <board
    width={`${BOARD_W}mm`}
    height="50mm"
    name="uNode32U4"
    // Layers: 2 (top + bottom). tscircuit's default; matches JLCPCB's
    // cheapest 2-layer offering.
    //
    // MANUFACTURING RULES. tscircuit's defaults are a fab's ABSOLUTE
    // minimums (0.10 mm trace/space, 0.20 mm-drill / 0.30 mm vias with a
    // 0.05 mm annular ring). This board is routed to standard 2-layer
    // rules with margin instead: 0.15 mm (6 mil) minimum trace width,
    // ≥ 0.115 mm copper clearance (JLCPCB/PCBWay standard minimum is
    // 0.10 mm), 0.15 mm via-to-pad clearance, and 0.30 mm-drill / 0.60 mm
    // vias (0.15 mm annular ring). The DRC gate enforces all of these.
    minTraceWidth="0.15mm"
    minTraceToPadEdgeClearance="0.115mm"
    minPadEdgeToPadEdgeClearance="0.115mm"
    minViaEdgeToPadEdgeClearance="0.15mm"
    minViaHoleDiameter="0.3mm"
    minViaPadDiameter="0.6mm"
    pcbStyle={{ viaHoleDiameter: "0.3mm", viaPadDiameter: "0.6mm" }}
  >
    {/* ══════════════════════════ §1 USB FRONT-END ══════════════════════════
        VBUS enters through a 500mA-hold PTC resettable fuse (F1) before it
        becomes the board's +5V rail (net.V5). D+/D− pass through 22Ω series
        resistors — the ATmega32U4 datasheet §2.2.8/9 mandates these: they
        damp reflections and limit inrush current through the chip's USB pads.
        The USB shell (4 through-hole legs + 4 SMD tabs) is soldered to GND
        for shielding and mechanical strength.
        J1 sits ON the board edge: its footprint origin is 2.75 mm inside the
        edge so the receptacle overhangs it by 0.7 mm (Amphenol drawing) —
        a micro-B plug's overmold can only seat if no board sticks out in
        front of the receptacle. */}

    <UsbMicroB name="J1" pcbX={-BOARD_W / 2 + USB_MICRO_B_EDGE_OFFSET_MM} pcbY={0} schX={-16} schY={0} />
    {/* F1 sits BELOW the D+/D− pair on purpose: its V5 exit then runs
        under the USB lines to the bulk caps instead of crossing them. */}
    <fuse
      name="F1"
      footprint="1206"
      currentRating="500mA"
      voltageRating="15V"
      pcbX={-27.95}
      pcbY={-2.2}
      schX={-10}
      schY={3}
    />
    {/* R1/R2 sit ~3mm from the MCU pads — datasheet §2.2.8/9 wants the
        series resistors “as close as possible” to the chip side. */}
    <resistor name="R1" resistance="22ohm" footprint="0603" pcbX={-12.5} pcbY={1.75} schX={-10} schY={0.5} />
    <resistor name="R2" resistance="22ohm" footprint="0603" pcbX={-12.5} pcbY={3.35} schX={-10} schY={-1} />

    <trace from=".J1 > .VBUS" to=".F1 > .left" width="0.5mm" />
    <trace from=".F1 > .right" to="net.V5" width="0.5mm" />
    <trace from=".J1 > .GND" to="net.GND" width="0.5mm" />
    <trace from=".J1 > .SHIELD1" to="net.GND" />
    <trace from=".J1 > .SHIELD2" to="net.GND" />
    <trace from=".J1 > .SHIELD3" to="net.GND" />
    <trace from=".J1 > .SHIELD4" to="net.GND" />
    <trace from=".J1 > .SHIELD5" to="net.GND" />
    <trace from=".J1 > .SHIELD6" to="net.GND" />
    {/* The two sides of a series resistor are DIFFERENT nets — only the
        connector side carries the USB_DP net label. */}
    <trace from=".J1 > .DPLUS" to=".R1 > .left" name="USB_DP" />
    <trace from=".R1 > .right" to=".U1 > .DPLUS" />
    <trace from=".J1 > .DMINUS" to=".R2 > .left" name="USB_DM" />
    <trace from=".R2 > .right" to=".U1 > .DMINUS" />

    {/* ══════════════════════════ §2 THE MCU ═══════════════════════════════
        The star of the show: one bare ATmega32U4-AU. All 44 pins are named
        in lib/atmega32u4.tsx — selectors like ".U1 > .VCC2" refer to those
        names. Rotation is 0 because tscircuit's tqfp44 numbers pins exactly
        like the datasheet (pin 1 = top-left), so USB pins (2-7) already face
        the left-edge connector. */}
    <Atmega32U4 name="U1" pcbX={-2} pcbY={0} schX={0} schY={0} />

    {/* ══════════════════════ §3 POWER INTEGRITY ═══════════════════════════
        A 32U4 board's #1 bring-up killer is sloppy decoupling. We follow the
        datasheet app-circuit discipline (Fig. 21-3, Fig. 24-10):
        • the two digital VCC pins (14, 34) each get their own 100nF ceramic
        • UVCC (pin 2, USB pad supply) gets 100nF
        • UCAP (pin 6, internal 3.3V regulator output) gets 1µF — §2.2.12
        • the TWO analog supply pins AVCC1 (24, ADC8-13 side) and AVCC2
          (44, ADC0-7 side) are each fed through their own ferrite bead
          (FB2, FB1) with 100nF at the pin. The datasheet's note under
          Fig. 24-10 asks for "the same circuitry ... on the ADC8-ADC13
          side" — tying pin 24 straight to +5V would also short out FB1's
          filtering, because both pins feed the same analog domain.
        • AREF (pin 42) gets 100nF (only matters if you use external AREF,
          but it costs nothing)
        • bulk at the power entry: 4.7µF + 1µF. USB 2.0 (§7.2.4.1) limits a
          device to 10µF on VBUS at attach — the whole V5 rail (bulk + every
          100nF) totals ≈ 6.4µF, so this board needs no soft-start circuit. */}
    {/* Placement discipline: one decoupler as close to the pin it serves as
        the fan-out allows, pin facing its pad. Each cap's pin1 is its
        supply side. C3→VCC1 (bottom-left), C5→VCC2 (top), C4→AVCC1
        (right, behind FB2), C6→AVCC2 (top-left, behind FB1), C8→UVCC
        (top-left), C7 is the UCAP 1µF, C9 bypasses AREF. */}
    {/* Bulk caps stand vertical — pin1 (V5) up, pin2 (GND) down — so the
        VBUS→V5 arrival from above and the GND return from the connector
        never have to cross each other at the power entry. */}
    <capacitor name="C1" capacitance="4.7uF" footprint="0805" pcbX={-23.45} pcbY={-3.5} pcbRotation={270} schX={-10} schY={-4} />
    <capacitor name="C2" capacitance="1uF" footprint="0805" pcbX={-18.95} pcbY={-4.5} pcbRotation={270} schX={-10} schY={-5.5} />
    <capacitor name="C3" capacitance="100nF" footprint="0603" pcbX={-8.5} pcbY={-10.5} pcbRotation={90} schX={-4} schY={-6} />
    {/* C4 tucks under the chip's bottom-right corner, vertical, pin1
        (AVCC1) on top: pin 24's escape drops straight down to it and never
        has to cross the right-edge signal corridor. FB2 feeds it from the
        right. */}
    <capacitor name="C4" capacitance="100nF" footprint="0603" pcbX={7.6} pcbY={-7.6} pcbRotation={270} schX={4} schY={-6} />
    <FerriteBead name="FB2" pcbX={10.2} pcbY={-7.6} pcbRotation={270} schX={2} schY={-7} />
    {/* C5 sits right of the other top caps: its GND pin then exits right
        toward J3.GND (the only GND member on that side of the board) while
        V5 arrives from the left — opposite shoulders, no squeeze. */}
    <capacitor name="C5" capacitance="100nF" footprint="0603" pcbX={5} pcbY={9} pcbRotation={90} schX={4} schY={6} />
    {/* C6 is vertical with pin1 (AVCC2) UP: the ferrite bead feeds it from
        the side, and GND4's escape reaches the bottom GND pin without
        wrapping past the AVCC2 pin. */}
    <capacitor name="C6" capacitance="100nF" footprint="0603" pcbX={-7} pcbY={9.4} pcbRotation={270} schX={-4} schY={6} />
    {/* C7 is rotated 180° so pin1 faces the MCU — the UCAP trace exits
        straight out of the pad, no detour around the cap body. */}
    <capacitor name="C7" capacitance="1uF" footprint="0603" pcbX={-13.5} pcbY={-2} pcbRotation={180} schX={-6} schY={-2.5} />
    <capacitor name="C8" capacitance="100nF" footprint="0603" pcbX={-11.5} pcbY={6} schX={-6} schY={4.5} />
    <capacitor name="C9" capacitance="100nF" footprint="0603" pcbX={-5} pcbY={9} pcbRotation={90} schX={0} schY={6.5} />
    <FerriteBead name="FB1" pcbX={-9.8} pcbY={8.5} schX={-6} schY={7} />

    {/* GND3↔GND4 hand-routed UNDER the top pad row (y=4.5 lane, below
        every pad tip at y=4.9): the autorouter sends this edge straight
        through the pad row, grazing AREF's pad. */}
    <trace
      from=".U1 > .GND3"
      to=".U1 > .GND4"
      pcbPath={[{ x: 3.2, y: 4.5 }, { x: -3.2, y: 4.5 }, ".U1 > .GND4"]}
    />

    {/* MCU power hookup — every pin explicit, because that's the lesson */}
    <trace from=".U1 > .VBUS" to="net.V5" />
    <trace from=".U1 > .UVCC" to="net.V5" />
    <trace from=".U1 > .VCC1" to="net.V5" />
    <trace from=".U1 > .VCC2" to="net.V5" />
    <trace from=".U1 > .UGND" to="net.GND" />
    <trace from=".U1 > .GND1" to="net.GND" width="0.25mm" />
    <trace from=".U1 > .GND2" to="net.GND" />
    <trace from=".U1 > .GND3" to="net.GND" />
    <trace from=".U1 > .GND4" to="net.GND" />

    {/* Bulk + per-pin decouplers (each cap spans supply↔GND, at its pin) */}
    <trace from=".C1 > .pin1" to="net.V5" />
    <trace from=".C1 > .pin2" to="net.GND" />
    <trace from=".C2 > .pin1" to="net.V5" />
    <trace from=".C2 > .pin2" to="net.GND" />
    <trace
      from=".U1 > .VCC1"
      to=".C3 > .pin1"
      width="0.25mm"
      maxLength="15mm"
      pcbPath={[{ x: -2.4, y: -6.9 }, { x: -7.5, y: -6.9 }, { x: -7.5, y: -11.3 }, ".C3 > .pin1"]}
    />
    <trace from=".C8 > .pin1" to="net.V5" />
    <trace from=".C8 > .pin2" to="net.GND" />
    {/* GND1 and VCC1 reach C3 through separate hand-routed lanes — the
        autorouter runs both as parallel diagonals that graze each other. */}
    <trace
      from=".U1 > .GND1"
      to=".C3 > .pin2"
      width="0.25mm"
      maxLength="15mm"
      pcbPath={[{ x: -1.6, y: -9.7 }, { x: -6.5, y: -9.7 }, ".C3 > .pin2"]}
    />
    <trace from=".C5 > .pin1" to="net.V5" />
    <trace from=".C5 > .pin2" to="net.GND" />

    {/* UCAP: internal 3.3V regulator output needs exactly 1µF (datasheet) */}
    <trace from=".U1 > .UCAP" to=".C7 > .pin1" name="UCAP" />
    <trace from=".C7 > .pin2" to="net.GND" />

    {/* AVCC2 (pin 44): +5V → FB1 → AVCC2, with local 100nF (C6) */}
    <trace from=".FB1 > .IN" to="net.V5" />
    <trace from=".FB1 > .OUT" to="net.AVCC2" />
    <trace from=".U1 > .AVCC2" to="net.AVCC2" />
    <trace from=".C6 > .pin1" to="net.AVCC2" />
    <trace from=".C6 > .pin2" to="net.GND" />

    {/* AVCC1 (pin 24): +5V → FB2 → AVCC1, with local 100nF (C4) */}
    <trace from=".FB2 > .IN" to="net.V5" />
    <trace from=".FB2 > .OUT" to="net.AVCC1" />
    <trace from=".U1 > .AVCC1" to="net.AVCC1" />
    <trace from=".C4 > .pin1" to="net.AVCC1" />
    <trace from=".C4 > .pin2" to="net.GND" />

    {/* AREF bypass */}
    <trace from=".U1 > .AREF" to="net.AREF" />
    <trace from=".C9 > .pin1" to="net.AREF" />
    <trace from=".C9 > .pin2" to="net.GND" />

    {/* ══════════════════════════ §4 CLOCK ═════════════════════════════════
        16MHz fundamental-mode parallel-resonant crystal between XTAL1/XTAL2,
        with 22pF load caps C10/C11 to GND — inside the datasheet's 12-22pF
        window for 8-16MHz crystals (Table 6-3). The math: a crystal specced
        CL = 15pF wants C = 2·(CL − Cstray) ≈ 2·(15 − 4) = 22pF. The full
        derivation is in the tutorial PDF.

        LAYOUT IS PART OF THE SPEC: tscircuit's crystal DRC enforces
        ≤10mm traces and 0 vias on both crystal nets (you can relax it with
        the maxTraceLength prop — don't). We keep every segment under 3mm:
        the caps sit between the chip and the crystal, one under each XTAL
        pad, and the crystal's pins are cross-assigned (pin1→XTAL2,
        pin2→XTAL1 — a crystal has no polarity, so this is free) so no
        trace crosses its neighbor. HC-49/S through-hole can = trivial to
        hand-solder; swap to a 3225 SMD crystal if you prefer. */}
    <crystal
      name="Y1"
      frequency="16MHz"
      loadCapacitance="15pF"
      footprint="hc49"
      pcbX={-0.8}
      pcbY={-14}
      schX={0}
      schY={-7}
    />
    {/* Crystal FIRST, caps BEHIND it: Y1 sits directly under the XTAL pads;
      C11/C10 hang vertically below Y1's own pads (crystal pin up, GND pin
      down), so every connection is a short axial drop and the load caps
      tie straight onto the crystal pins — the classic ATmega app-note
      arrangement. Y1 cross-assigned (pin1→XTAL2, pin2→XTAL1; no polarity). */}
    <capacitor name="C10" capacitance="22pF" footprint="0603" pcbX={1.64} pcbY={-18.5} pcbRotation={270} schX={-3} schY={-9} />
    <capacitor name="C11" capacitance="22pF" footprint="0603" pcbX={-3.24} pcbY={-18.5} pcbRotation={270} schX={3} schY={-9} />

    {/* Net-based on purpose: with Y1 between the pads and its caps, the
        minimum spanning tree pairs pad↔Y1 and Y1↔cap — exactly the two
        short axial hops the layout provides. */}
    <trace from=".U1 > .XTAL2" to="net.XTAL2" />
    <trace from=".Y1 > .pin1" to="net.XTAL2" />
    <trace from=".C11 > .pin1" to="net.XTAL2" />
    <trace from=".C11 > .pin2" to="net.GND" />
    <trace from=".U1 > .XTAL1" to="net.XTAL1" />
    <trace from=".Y1 > .pin2" to="net.XTAL1" />
    <trace from=".C10 > .pin1" to="net.XTAL1" />
    <trace from=".C10 > .pin2" to="net.GND" />

    {/* ═════════════════════ §5 RESET & BOOTLOADER ═════════════════════════
        RESET (pin 13, active-low): 10k pull-up to 5V + tactile button to
        GND (SW1). tscircuit's pushbutton has 4 pins, internally connected
        in pairs (1=2, 3=4), so wiring pin1 + pin3 is enough.

        BOOT (PE2 / pin 33 / #HWB): 10k pull-up keeps normal boot. With the
        HWBE fuse PROGRAMMED, holding SW2 while releasing RESET forces the
        boot-loader reset vector (datasheet §27.5.3, Fig. 27-3). That is
        exactly the state of a FACTORY-FRESH ATmega32U4-AU: it ships with a
        USB (DFU) bootloader and HWBE programmed (datasheet p.1, Table
        28-3), so SW2+SW1 reach it with no ISP programmer at all.
        After the Leonardo fuses are written (efuse 0xCB → HWBE
        UNprogrammed, hfuse 0xD8 → BOOTRST programmed) the chip enters the
        Caterina bootloader on EVERY reset anyway, so SW2 is then simply a
        user button on PE2 (header pin HWB). */}
    <resistor name="R3" resistance="10kohm" footprint="0603" pcbX={-19.5} pcbY={2.3} schX={10} schY={-3} />
    <pushbutton name="SW1" footprint="pushbutton" pcbX={-19.5} pcbY={10} schX={14} schY={-3} />
    <resistor name="R4" resistance="10kohm" footprint="0603" pcbX={-24.5} pcbY={-16.5} schX={10} schY={-6} />
    <pushbutton name="SW2" footprint="pushbutton" pcbX={-30.5} pcbY={-15} schX={14} schY={-6} />

    {/* R3/R4 V5 feed: explicit daisy-chain R3←R4←J2.V5. A plain net.V5
        connection would let the MST wrap R3's feed around C2's GND pin
        (both bulk caps have their GND pin on the bottom) — this way the
        pull-ups draw from the header pin through the quiet corner. */}
    <trace from=".R3 > .left" to="net.V5" />
    <trace from=".R4 > .left" to="net.V5" />
    <trace from=".R3 > .right" to="net.RST" />
    <trace from=".U1 > .RESET" to="net.RST" />
    <trace from=".SW1 > .pin1" to="net.RST" />
    <trace from=".SW1 > .pin3" to="net.GND" />

    <trace from=".R4 > .right" to="net.HWB" />
    <trace from=".U1 > .PE2" to="net.HWB" />
    <trace from=".SW2 > .pin1" to="net.HWB" />
    <trace from=".SW2 > .pin3" to="net.GND" />

    {/* ══════════════════════════ §6 ICSP HEADER ═══════════════════════════
        Standard 2×3 AVR ISP header — this is how you program the BLANK chip
        the first time (bootloader + fuses).

        ⚠️ LABEL ORDER MATTERS. With doubleRow + pcbRotation={90}, tscircuit
        numbers the pads in a ring: pin1 bottom-left, pin2 bottom-right,
        pin3 mid-right, pin4 top-right, pin5 top-left, pin6 mid-left. The
        pinLabels array below is arranged so the PHYSICAL layout comes out
        as the standard AVR ISP grid every programmer cable expects:

              MISO   VCC
              SCK    MOSI
              RESET  GND

        Get this wrong and a keyed ISP cable would put VCC where GND
        belongs — the proof script (npm run proof) asserts the physical
        arrangement, so it can never silently regress. */}
    <pinheader
      name="J3"
      pinCount={6}
      doubleRow
      pitch="2.54mm"
      pinLabels={["RESET", "GND", "MOSI", "VCC", "MISO", "SCK"]}
      showSilkscreenPinLabels
      pcbX={-22}
      pcbY={-12}
      schX={16}
      schY={2}
    />
    <trace from=".J3 > .MISO" to="net.MISO" />
    <trace from=".J3 > .SCK" to="net.SCK" />
    <trace from=".J3 > .MOSI" to="net.MOSI" />
    <trace from=".J3 > .VCC" to="net.V5" />
    <trace from=".J3 > .GND" to="net.GND" />
    <trace from=".J3 > .RESET" to="net.RST" />

    {/* SPI nets join the MCU (these pins are also Arduino D14-D16 on J4) */}
    <trace from=".U1 > .PB3" to="net.MISO" />
    <trace from=".U1 > .PB1" to="net.SCK" />
    <trace from=".U1 > .PB2" to="net.MOSI" />

    {/* ══════════════════════════ §7 INDICATORS ═══════════════════════════
        Four LEDs in a row under the top header, each with a worked current
        calculation in the tutorial:
        • PWR  — green,   V5 → LED → 1k → GND      (always on; ~3mA)
        • L    — amber,   PC7 → 1k → LED → GND     (Arduino D13, active-HIGH)
        • TX   — amber,   V5 → LED → 1k → PD5      (active-LOW: the Arduino
          core's TXLED1 macro drives the pin LOW to light it)
        • RX   — amber,   V5 → LED → 1k → PB0      (active-LOW, RXLED1 macro)
        LED pins: .pos = anode, .neg = cathode. */}
    <led name="LED1" color="green" footprint="led0603" pcbX={-9.5} pcbY={16} schX={-10} schY={-11} />
    <resistor name="R5" resistance="1kohm" footprint="0603" pcbX={-6} pcbY={16} schX={-8} schY={-11} />
    <led name="LED2" color="amber" footprint="led0603" pcbX={1} pcbY={16} schX={-10} schY={-13.5} />
    <resistor name="R6" resistance="1kohm" footprint="0603" pcbX={-2.5} pcbY={16} schX={-8} schY={-13.5} />
    <led name="LED3" color="amber" footprint="led0603" pcbX={4.5} pcbY={16} schX={-10} schY={-16} />
    <resistor name="R7" resistance="1kohm" footprint="0603" pcbX={8} pcbY={16} schX={-8} schY={-16} />
    <led name="LED4" color="amber" footprint="led0603" pcbX={11.5} pcbY={16} schX={-10} schY={-18.5} />
    <resistor name="R8" resistance="1kohm" footprint="0603" pcbX={15} pcbY={16} schX={-8} schY={-18.5} />

    {/* PWR: on whenever 5V is present */}
    <trace from=".LED1 > .pos" to="net.V5" />
    <trace from=".LED1 > .neg" to=".R5 > .left" />
    <trace from=".R5 > .right" to="net.GND" />

    {/* L on D13/PC7 — active-high like every Arduino */}
    <trace from=".U1 > .PC7" to="net.D13" />
    <trace from=".R6 > .left" to="net.D13" />
    <trace from=".R6 > .right" to=".LED2 > .pos" />
    <trace from=".LED2 > .neg" to="net.GND" />

    {/* TX/RX — active-low, wired from 5V INTO the pin */}
    {/* The LED3→LED4 V5 hop is hand-routed BELOW the LED row (pcbPath):
        the autorouter prefers the lane above the row, where it fights the
        SPI traces going to the top header. */}
    <trace from=".LED3 > .pos" to=".LED4 > .pos" pcbPathRelativeTo=".LED3 > .pos" pcbPath={[{ x: 0, y: -1.3 }, { x: 6.17, y: -1.3 }, ".LED4 > .pos"]} />
    <trace from=".LED3 > .pos" to="net.V5" />
    <trace from=".LED3 > .neg" to=".R7 > .left" />
    <trace from=".R7 > .right" to=".U1 > .PD5" name="TXLED" />
    <trace from=".LED4 > .pos" to="net.V5" />
    <trace from=".LED4 > .neg" to=".R8 > .left" />
    <trace from=".R8 > .right" to="net.SS" />

    {/* PB0 is both the RX LED pin and Arduino D17/SS */}
    <trace from=".U1 > .PB0" to="net.SS" />

    {/* ══════════════════════════ §8 I²C PULL-UPS ══════════════════════════
        4.7k pull-ups on SDA (PD1/D2) and SCL (PD0/D3) so any I²C sensor
        works out of the box. They're weak enough (1mA max) to not disturb
        ordinary GPIO use of D2/D3. */}
    <resistor name="R9" resistance="4.7kohm" footprint="0603" pcbX={7.6} pcbY={-14.8} pcbRotation={180} schX={10} schY={4} />
    <resistor name="R10" resistance="4.7kohm" footprint="0603" pcbX={7.6} pcbY={-13} pcbRotation={180} schX={10} schY={1.5} />

    <trace from=".R9 > .left" to="net.V5" />
    <trace from=".R9 > .right" to="net.SDA" />
    <trace from=".U1 > .PD1" to="net.SDA" />
    <trace from=".R10 > .left" to="net.V5" />
    <trace from=".R10 > .right" to="net.SCL" />
    <trace from=".U1 > .PD0" to="net.SCL" />

    {/* ══════════════════════ §9 BREAKOUT HEADERS ══════════════════════════
        J2 (right edge, vertical): the digital bus — D0-D13 in Leonardo
        order, power at the bottom end. Running it down the right edge
        means the right-side MCU ports (PB4-PB7, PC6/PC7, PD4/4/6/7)
        escape STRAIGHT OUT instead of carving through the chip's fan-out
        — the single most important placement decision on this board.
        J4 (top): analog + I²C + SPI + HWB + AREF, power at the USB end.
        Labels are silkscreened 1:1 — build a breadboard harness and the
        names match every Arduino Leonardo tutorial on the internet. */}
    <pinheader
      name="J2"
      pinCount={16}
      pitch="2.54mm"
      gender="male"
      pinLabels={[
        "V5", "GND",
        "D13", "D12", "D11", "D10", "D9", "D8", "D7", "D6",
        "D5", "D4", "D3", "D2", "D1", "D0",
      ]}
      showSilkscreenPinLabels
      pcbX={34}
      pcbY={0}
      pcbRotation={90}
      schX={16}
      schY={-10}
      schRotation={90}
    />
    <pinheader
      name="J4"
      pinCount={16}
      pitch="2.54mm"
      gender="male"
      pinLabels={[
        "V5", "GND", "AREF",
        "A0", "A1", "A2", "A3", "A4", "A5",
        "SCL", "SDA", "MISO", "SCK", "MOSI", "SS", "HWB",
      ]}
      showSilkscreenPinLabels
      pcbX={0}
      pcbY={22}
      schX={16}
      schY={10}
      schRotation={90}
    />

    {/* J2/J4 power */}
    <trace from=".J2 > .V5" to="net.V5" />
    <trace from=".J2 > .GND" to="net.GND" />
    <trace from=".J4 > .V5" to="net.V5" />
    <trace from=".J4 > .GND" to="net.GND" />

    {/* Digital pass-throughs (MCU port ↔ header pin) */}
    <trace from=".J2 > .D13" to="net.D13" />
    <trace from=".U1 > .PD6" to=".J2 > .D12" name="D12" />
    <trace from=".U1 > .PB7" to=".J2 > .D11" name="D11" />
    <trace from=".U1 > .PB6" to=".J2 > .D10" name="D10" />
    <trace from=".U1 > .PB5" to=".J2 > .D9" name="D9" />
    <trace from=".U1 > .PB4" to=".J2 > .D8" name="D8" />
    <trace from=".U1 > .PE6" to=".J2 > .D7" name="D7" />
    <trace from=".U1 > .PD7" to=".J2 > .D6" name="D6" />
    <trace from=".U1 > .PC6" to=".J2 > .D5" name="D5" />
    <trace from=".U1 > .PD4" to=".J2 > .D4" name="D4" />
    <trace from=".J2 > .D3" to="net.SCL" />
    <trace from=".J2 > .D2" to="net.SDA" />
    <trace from=".U1 > .PD3" to=".J2 > .D1" name="D1" />
    <trace from=".U1 > .PD2" to=".J2 > .D0" name="D0" />

    {/* Analog + I²C + SPI on J4 */}
    <trace from=".U1 > .PF7" to=".J4 > .A0" name="A0" />
    <trace from=".U1 > .PF6" to=".J4 > .A1" name="A1" />
    <trace from=".U1 > .PF5" to=".J4 > .A2" name="A2" />
    <trace from=".U1 > .PF4" to=".J4 > .A3" name="A3" />
    <trace from=".U1 > .PF1" to=".J4 > .A4" name="A4" />
    <trace from=".U1 > .PF0" to=".J4 > .A5" name="A5" />
    <trace from=".J4 > .AREF" to="net.AREF" />
    <trace from=".J4 > .SCL" to="net.SCL" />
    <trace from=".J4 > .SDA" to="net.SDA" />
    <trace from=".J4 > .MISO" to="net.MISO" />
    <trace from=".J4 > .SCK" to="net.SCK" />
    <trace from=".J4 > .MOSI" to="net.MOSI" />
    <trace from=".J4 > .SS" to="net.SS" />
    <trace from=".J4 > .HWB" to="net.HWB" />

    {/* ═════════════════════ MECHANICAL & IDENTIFICATION ══════════════════
        4× M3 mounting holes (3.2mm, unplated) and board identification
        silkscreen. Unplated holes = no net = pure mechanical. */}
    <hole name="H1" diameter="3.2mm" pcbX={-32} pcbY={22} />
    <hole name="H2" diameter="3.2mm" pcbX={28} pcbY={22} />
    <hole name="H3" diameter="3.2mm" pcbX={28} pcbY={-22} />
    <hole name="H4" diameter="3.2mm" pcbX={-32} pcbY={-22} />

    <silkscreentext text="uNode32U4" pcbX={19} pcbY={-5} fontSize="1.2mm" />
    <silkscreentext text="bare ATmega32U4" pcbX={19} pcbY={-7} fontSize="0.8mm" />
    <silkscreentext text="RST" pcbX={-19.5} pcbY={4.9} fontSize="1mm" />
    <silkscreentext text="BOOT" pcbX={-30.5} pcbY={-19.4} fontSize="1mm" />
    <silkscreentext text="ICSP" pcbX={-22} pcbY={-8.2} fontSize="1mm" />

    {/* ═══════════════════════ §10 GROUND POUR ═══════════════════════════
        The single biggest upgrade from "beginner board" to "real board":
        a solid GND plane on the bottom layer. Every GND pin gets a short
        via to the plane instead of a long routed trace, return currents
        flow under their signals, EMI drops, and the top layer keeps
        almost all the routing room for signals. Thermal reliefs keep
        through-hole pads solderable (heat doesn't flood into the plane).
        This is THE standard 2-layer stackup: signals on top, GND below. */}
    <copperpour
      connectsTo="net.GND"
      layer="bottom"
      padMargin="0.45mm"
      useThermalReliefs
    />
  </board>
)
